type SearchRow = { code?: string; name?: string };

function normalizeSearchRows(
  raw: SearchRow[] | { items?: SearchRow[] } | null | undefined,
): MasterLookupItem[] {
  const rows = Array.isArray(raw) ? raw : raw?.items ?? [];
  return rows
    .filter((r) => r.code && r.code !== 'QL.22')
    .map((r) => ({
      value: String(r.code),
      label: r.name ? `${r.code} — ${r.name}` : String(r.code),
    }));
}

/** SSOT `search-input.md` — không dấu · CI · space. */
export function normalizeSearchText(value?: string): string {
  return (value ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

/** Tên only — cấm nhét mã vào secondary (`QL.1 — QL.1 — Quốc lộ 1`). */
export function routeNameOnly(item: MasterLookupItem): string {
  const sep = ' — ';
  const prefix = `${item.value}${sep}`;
  if (item.label.startsWith(prefix)) return item.label.slice(prefix.length);
  return item.label === item.value ? '' : item.label;
}

function filterSeed(search?: string): MasterLookupItem[] {
  const q = normalizeSearchText(search);
  if (!q) return ROAD_ROUTE_SEED;
  return ROAD_ROUTE_SEED.filter(
    (i) =>
      normalizeSearchText(i.value).includes(q) || normalizeSearchText(i.label).includes(q),
  );
}

async function searchRoadRoutes(search?: string): Promise<MasterLookupItem[]> {
  try {
    const qs = new URLSearchParams();
    if (search) qs.set('search', search);
    qs.set('page', '1');
    qs.set('pageSize', '50');
    const res = await apiClient.get<BffResponse<SearchRow[] | { items?: SearchRow[] }>>(
      `/integration/road-routes/search?${qs}`,
    );
    const items = normalizeSearchRows(unwrap(res));
    if (items.length > 0) return items;
    return filterSeed(search);
  } catch {
    return filterSeed(search);
  }
}

export function lookupLabel(items: MasterLookupItem[], value: string): string {
  return items.find((i) => i.value === value)?.label ?? value;
}

export function lookupNameOnly(items: MasterLookupItem[], value: string): string {
  const item = items.find((i) => i.value === value);
  return item ? routeNameOnly(item) : '';
}

export const ROAD_ROUTE_LOOKUP_CONFIG: SearchInputConfig<MasterLookupItem> = {
  api: {
    getItemKey: (i) => i.value,
    search: async ({ search }) => {
      const items = await searchRoadRoutes(search);
      return { items, page: 1, totalPages: 1 };
    },
    getDetail: async (id) => {
      const seed = ROAD_ROUTE_SEED.find((i) => i.value === id);
      if (seed) return seed;
      const items = await searchRoadRoutes(id);
      return items.find((i) => i.value === id) ?? { value: id, label: id };
    },
  },
  display: {
    getPrimaryDisplay: (i) => i.label,
    getSecondaryDisplay: (i) => routeNameOnly(i),
    getSingleDisplay: (i) => routeNameOnly(i) || i.label,
  },
  ...SEARCH_DROPDOWN_PORTAL,
    columns: catalogLookupColumns(),
    header: catalogLookupHeader(),
  pageSize: 50,
};
