import { apiClient, unwrap, type BffResponse } from '../api';
import type {
  CatalogUiSchema,
  SaveCatalogUiSchema,
} from '@linm-soft-org/linm-web-common-components';

const base = (catalogKind: string) =>
  `/integration/catalogs/${encodeURIComponent(catalogKind)}/ui-schema`;

export type SaveCatalogUiSchemaBody = SaveCatalogUiSchema & {
  bootstrapFromUi?: boolean;
};

export const catalogUiSchemaService = {
  get: async (
    catalogKind: string,
    configMode = false,
  ): Promise<CatalogUiSchema> => {
    const qs = configMode ? '?configMode=true' : '';
    const res = await apiClient.get<BffResponse<CatalogUiSchema>>(
      `${base(catalogKind)}${qs}`,
    );
    return unwrap(res)!;
  },

  save: async (
    catalogKind: string,
    body: SaveCatalogUiSchemaBody,
  ): Promise<CatalogUiSchema> => {
    const res = await apiClient.put<BffResponse<CatalogUiSchema>>(
      base(catalogKind),
      body,
    );
    return unwrap(res)!;
  },
};
