import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useDispatch } from 'react-redux';
import { useSearchParams } from 'react-router-dom';
import {
  Button,
  DEFAULT_CATALOG_LIST_TABLE_CONFIG,
  LIN_ERP_LIST_FILTER_LAYOUT,
  LinCatalogDataGrid,
  LinCatalogHistoryModal,
  LinCatalogListPagination,
  LinCatalogRowActionMenu,
  LinCatalogUiSchemaEditorModal,
  LinErpListFilterBar,
  LinPageLayout,
  SearchInput,
  SearchTextInput,
  Select,
  buildCatalogRowMenuItems,
  catalogListTableConfigFromSchema,
  dispatchAppToast,
  useCatalogHistoryModal,
  useErpListSelection,
  useServerPagedListLoading,
  type ErpListTableConfig,
  type LinCatalogRowMenuItem,
} from '@linm-soft-org/linm-web-common-components';
import { useCatalogUiSchema } from '../../hooks/useCatalogUiSchema';
import { incidentService } from '../../services/incident/incidentService';
import { incidentListPermissions } from '../../services/incident/permissions';
import type { IncidentDto, IncidentLookupOption } from '../../services/incident/responseModel';
import { catalogUiSchemaService } from '../../services/catalogUiSchema/catalogUiSchemaService';
import {
  buildDynamicGridColumns,
  type UiListColumnBootstrap,
} from '../../utils/bootstrapCatalogUiSchema';
import {
  FALLBACK_INIT_DATA,
  severityLabel,
  statusLabel,
  typeLabel,
} from '../../demo/incidentStore';
import {
  ROAD_ROUTE_LOOKUP_CONFIG,
  ROAD_ROUTE_SEED,
  lookupNameOnly,
} from '../../services/attendance/lookups';
import { useInAppNavigate } from '../../router/navigateInAppPath';
import { type IncidentFormMode } from './IncidentFormSlideout';

const LIST_PATH = '/su-co';
import { GiaoViecModal, type GiaoViecContextIncident } from '../../components/GiaoViecModal';
import { TaskChatPanel, type TaskChatTarget } from '../../components/TaskChatPanel/TaskChatPanel';
import {
  isPlatformTaskIntegrationReady,
  platformTaskPrereqTooltip,
} from '../../utils/platformTaskPrereq';
import {
  canSuggestTaskFromIncident,
  incidentSeverityPrefill,
} from '../../utils/taskPriorityPrefill';
import styles from './IncidentListPage.module.css';
import { fromCatalogToolbar } from '../buildRmmsGenericToolbar';

const TEST_ID = 'rmms-incident-list';
const PAGE_ID = 'incident';
const CATALOG_KIND = 'incidents';
const ROW_MENU_HINT_KEY = `${TEST_ID}-row-menu-hint-dismissed`;

function formatRequested(iso: string): string {
  if (!iso) return '—';
  try {
    return new Date(iso).toLocaleString('vi-VN');
  } catch {
    return iso;
  }
}

const IncidentListPage: React.FC = () => {
  const dispatch = useDispatch();
  const catalogHistory = useCatalogHistoryModal();
  const navigate = useInAppNavigate();
  const [searchParams] = useSearchParams();
  const perms = incidentListPermissions();
  const { schema, reload: reloadSchema } = useCatalogUiSchema(CATALOG_KIND);

  const [searchDraft, setSearchDraft] = useState('');
  const [statusDraft, setStatusDraft] = useState('');
  const [severityDraft, setSeverityDraft] = useState('');
  const [routeDraft, setRouteDraft] = useState('');
  const [typeDraft, setTypeDraft] = useState('');
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [severityFilter, setSeverityFilter] = useState('');
  const [routeFilter, setRouteFilter] = useState('');
  const [typeFilter, setTypeFilter] = useState('');
  const [initStatuses, setInitStatuses] = useState<IncidentLookupOption[]>(
    FALLBACK_INIT_DATA.statuses,
  );
  const [initSeverities, setInitSeverities] = useState<IncidentLookupOption[]>(
    FALLBACK_INIT_DATA.severities,
  );
  const [initTypes, setInitTypes] = useState<IncidentLookupOption[]>(
    FALLBACK_INIT_DATA.incidentTypes,
  );
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState<number>(50);
  const [items, setItems] = useState<IncidentDto[]>([]);
  const [totalCount, setTotalCount] = useState(0);
  const [rowMenu, setRowMenu] = useState<{
    x: number;
    y: number;
    row: IncidentDto;
  } | null>(null);
  const [configOpen, setConfigOpen] = useState(false);
  const [pendingDelete, setPendingDelete] = useState<IncidentDto | null>(null);
  const [pendingClose, setPendingClose] = useState<IncidentDto | null>(null);
  const [giaoViecOpen, setGiaoViecOpen] = useState(false);
  const [giaoViecContext, setGiaoViecContext] = useState<GiaoViecContextIncident | null>(null);
  const [chatTarget, setChatTarget] = useState<TaskChatTarget | null>(null);
  const platformReady = isPlatformTaskIntegrationReady();
  const [tableConfig, setTableConfig] = useState<ErpListTableConfig>(() => ({
    ...DEFAULT_CATALOG_LIST_TABLE_CONFIG,
    ...catalogListTableConfigFromSchema(undefined),
    resizable: true,
  }));

  useEffect(() => {
    if (!schema?.list) return;
    setTableConfig({
      ...DEFAULT_CATALOG_LIST_TABLE_CONFIG,
      ...catalogListTableConfigFromSchema(schema.list),
      resizable: true,
    });
  }, [schema]);

  const {
    showTableLoading,
    pageLoading,
    pulseSearch,
    setLoadingMode,
    beginFetch,
    endFetch,
  } = useServerPagedListLoading();

  const load = useCallback(() => {
    beginFetch();
    incidentService
      .getList({
        search: search.trim() || undefined,
        status: statusFilter || undefined,
        severity: severityFilter || undefined,
        routeName: routeFilter || undefined,
        incidentType: typeFilter || undefined,
        page,
        pageSize,
      })
      .then((res) => {
        setItems(res.items);
        setTotalCount(res.totalCount);
      })
      .catch(() => {
        setItems([]);
        setTotalCount(0);
      })
      .finally(() => endFetch());
  }, [
    search,
    statusFilter,
    severityFilter,
    routeFilter,
    typeFilter,
    page,
    pageSize,
    beginFetch,
    endFetch,
  ]);

  useEffect(() => {
    let cancelled = false;
    void incidentService.getInitData().then((data) => {
      if (cancelled || !data) return;
      if (data.statuses?.length) setInitStatuses(data.statuses);
      if (data.severities?.length) setInitSeverities(data.severities);
      if (data.incidentTypes?.length) setInitTypes(data.incidentTypes);
    });
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    let cancelled = false;
    const t = window.setTimeout(() => {
      if (!cancelled) load();
    }, 0);
    return () => {
      cancelled = true;
      window.clearTimeout(t);
    };
  }, [load]);

  useEffect(() => {
    const form = searchParams.get('form');
    if (!form) return;
    const id = searchParams.get('id');
    if (form === 'create') {
      navigate(`${LIST_PATH}/tao-moi`, { replace: true });
      return;
    }
    if (!id) return;
    if (form === 'edit') {
      navigate(`${LIST_PATH}/sua?id=${encodeURIComponent(id)}`, { replace: true });
    } else if (form === 'copy') {
      navigate(`${LIST_PATH}/tao-moi?copyFrom=${encodeURIComponent(id)}`, { replace: true });
    } else {
      navigate(`${LIST_PATH}/${encodeURIComponent(id)}`, { replace: true });
    }
  }, [searchParams, navigate]);

  const listSelection = useErpListSelection<IncidentDto>({
    rows: items,
    totalCount,
    page,
    pageSize,
    getRowId: (r) => r.id,
  });
  const { activeRow, selectActiveRow, clearSelection } = listSelection;

  const applyFilters = useCallback(
    (
      nextSearch: string,
      nextStatus: string,
      nextSeverity: string,
      nextRoute: string,
      nextType: string,
    ) => {
      pulseSearch(() => {
        setSearch(nextSearch.trim());
        setStatusFilter(nextStatus);
        setSeverityFilter(nextSeverity);
        setRouteFilter(nextRoute);
        setTypeFilter(nextType);
        setPage(1);
      });
    },
    [pulseSearch],
  );

  const handleSearchClick = useCallback(() => {
    applyFilters(searchDraft, statusDraft, severityDraft, routeDraft, typeDraft);
  }, [applyFilters, searchDraft, statusDraft, severityDraft, routeDraft, typeDraft]);

  const handleStatusChange = useCallback((value: string) => {
    setStatusDraft(value);
    setPage(1);
  }, []);

  const handleSeverityChange = useCallback((value: string) => {
    setSeverityDraft(value);
    setPage(1);
  }, []);

  const handleRouteChange = useCallback((value: string) => {
    setRouteDraft(value);
    setPage(1);
  }, []);

  const handleTypeChange = useCallback((value: string) => {
    setTypeDraft(value);
    setPage(1);
  }, []);

  useEffect(() => {
    const t = window.setTimeout(() => {
      applyFilters(searchDraft, statusDraft, severityDraft, routeDraft, typeDraft);
    }, 300);
    return () => window.clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps -- only re-filter when draft inputs change
  }, [searchDraft, statusDraft, severityDraft, routeDraft, typeDraft]);

  const statusOptions = useMemo(
    () => [
      { value: '', label: 'Tất cả' },
      ...initStatuses.map((t) => ({
        value: t.value,
        label: t.label || statusLabel(t.value),
      })),
    ],
    [initStatuses],
  );

  const severityOptions = useMemo(
    () => [
      { value: '', label: 'Tất cả' },
      ...initSeverities.map((t) => ({
        value: t.value,
        label: t.label || severityLabel(t.value),
      })),
    ],
    [initSeverities],
  );

  const typeOptions = useMemo(
    () => [
      { value: '', label: 'Tất cả' },
      ...initTypes.map((t) => ({
        value: t.value,
        label: t.label || typeLabel(t.value),
      })),
    ],
    [initTypes],
  );

  const openRow = useCallback(
    (row: IncidentDto, mode: IncidentFormMode) => {
      selectActiveRow(row);
      let next = mode;
      if (mode === 'edit' && !perms.canUpdate) next = 'view';
      if (mode === 'copy' && !perms.canCreate) next = 'view';
      if (next === 'edit') {
        navigate(`${LIST_PATH}/sua?id=${encodeURIComponent(row.id)}`);
      } else if (next === 'copy') {
        navigate(`${LIST_PATH}/tao-moi?copyFrom=${encodeURIComponent(row.id)}`);
      } else if (next === 'create') {
        navigate(`${LIST_PATH}/tao-moi`);
      } else {
        navigate(`${LIST_PATH}/${encodeURIComponent(row.id)}`);
      }
    },
    [selectActiveRow, perms.canUpdate, perms.canCreate, navigate],
  );

  const openCreate = useCallback(() => {
    if (!perms.canCreate) return;
    navigate(`${LIST_PATH}/tao-moi`);
  }, [perms.canCreate, navigate]);

  const reloadAll = useCallback(() => {
    setLoadingMode('filter');
    load();
  }, [load, setLoadingMode]);

  const handlePageChange = useCallback((next: number) => {
    setPage(next);
  }, []);

  const handlePageSizeChange = useCallback((next: number) => {
    setPageSize(next);
    setPage(1);
  }, []);

  const handleHistoryToolbar = useCallback(() => {
    if (!activeRow) {
      dispatchAppToast(dispatch, {
        message: 'Chọn một dòng (menu dòng) rồi mở Lịch sử.',
        type: 'info',
      });
      return;
    }
    catalogHistory.openHistory({
      documentType: PAGE_ID,
      documentId: activeRow.id,
      documentCode: activeRow.code,
    });
  }, [activeRow, catalogHistory.openHistory, dispatch]);

  const openConfig = useCallback(() => {
    setConfigOpen(true);
  }, []);

  const requestDelete = useCallback(
    (row: IncidentDto) => {
      if (!perms.canDelete) {
        dispatchAppToast(dispatch, {
          message: 'Không có quyền xóa sự cố.',
          type: 'warning',
        });
        return;
      }
      setPendingDelete(row);
    },
    [perms.canDelete, dispatch],
  );

  const confirmDelete = useCallback(async () => {
    const row = pendingDelete;
    if (!row) return;
    setPendingDelete(null);
    try {
      await incidentService.delete(row.id);
      dispatchAppToast(dispatch, {
        message: `Đã xóa sự cố ${row.code}`,
        type: 'success',
      });
      clearSelection();
      setLoadingMode('filter');
      load();
    } catch (err) {
      dispatchAppToast(dispatch, {
        message: err instanceof Error ? err.message : 'Xóa sự cố thất bại.',
        type: 'error',
      });
    }
  }, [pendingDelete, dispatch, clearSelection, setLoadingMode, load]);

  const openGiaoViec = useCallback(
    (row: IncidentDto) => {
      if (!platformReady) {
        dispatchAppToast(dispatch, {
          message: platformTaskPrereqTooltip(),
          type: 'info',
        });
        return;
      }
      if (!canSuggestTaskFromIncident(row.severity, row.status)) {
        dispatchAppToast(dispatch, {
          message: 'Sự cố đã đóng hoặc mức thấp — không gợi ý tạo công việc.',
          type: 'info',
        });
        return;
      }
      const prefill = incidentSeverityPrefill(row.severity);
      if (!prefill) return;
      setGiaoViecContext({
        source: 'incident',
        sourceEntityType: 'incident',
        sourceEntityId: row.id,
        incidentCode: row.code,
        title: row.title || `Xử lý sự cố — ${row.code}`,
        severity: row.severity,
        description: row.description,
        priority: prefill.priority,
        assignmentStrategy: 'direct',
        dueDate: prefill.dueDate,
      });
      setGiaoViecOpen(true);
    },
    [dispatch, platformReady],
  );

  const requestClose = useCallback(
    (row: IncidentDto) => {
      if (!perms.canUpdate) return;
      if (row.status === 'closed') {
        dispatchAppToast(dispatch, {
          message: `${row.code} đã đóng.`,
          type: 'info',
        });
        return;
      }
      setPendingClose(row);
    },
    [perms.canUpdate, dispatch],
  );

  const dismissClose = useCallback(() => {
    setPendingClose(null);
  }, []);

  useEffect(() => {
    if (!pendingClose) return undefined;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        e.preventDefault();
        dismissClose();
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [pendingClose, dismissClose]);

  const confirmClose = useCallback(async () => {
    const row = pendingClose;
    if (!row) return;
    setPendingClose(null);
    try {
      await incidentService.close(row.id);
      dispatchAppToast(dispatch, {
        message: `Đã đóng sự cố ${row.code}`,
        type: 'success',
      });
      setLoadingMode('filter');
      load();
    } catch (err) {
      dispatchAppToast(dispatch, {
        message: err instanceof Error ? err.message : 'Không đóng được sự cố.',
        type: 'error',
      });
    }
  }, [pendingClose, dispatch, setLoadingMode, load]);

  const catalogToolbar = useMemo(
    () => ({
      testIdPrefix: TEST_ID,
      onRefresh: reloadAll,
      canAdd: perms.canCreate,
      onAdd: openCreate,
      canHistory: true,
      onHistory: handleHistoryToolbar,
      showSchemaConfig: true,
      onEditConfig: openConfig,
      showEdit: Boolean(activeRow && perms.canUpdate),
      showView: Boolean(activeRow && perms.canRead),
      onEdit: activeRow ? () => openRow(activeRow, 'edit') : undefined,
      onView: activeRow ? () => openRow(activeRow, 'view') : undefined,
      canDelete: Boolean(activeRow && perms.canDelete),
      onDelete: activeRow
        ? () => {
            requestDelete(activeRow);
          }
        : undefined,
    }),
    [
      reloadAll,
      perms.canCreate,
      perms.canUpdate,
      perms.canRead,
      perms.canDelete,
      openCreate,
      handleHistoryToolbar,
      openConfig,
      activeRow,
      openRow,
      requestDelete,
    ],
  );

  const listFilters = useMemo(
    () => (
      <LinErpListFilterBar
        testIdPrefix={TEST_ID}
        hideDateRange
        onSearch={handleSearchClick}
        searchAriaLabel="Tìm"
        loading={showTableLoading}
        leading={(
          <>
            <div data-testid={`${TEST_ID}-field-search`}>
              <SearchTextInput
                label="Tìm kiếm"
                placeholder="Mã / tiêu đề / đoạn / DET…"
                value={searchDraft}
                onChange={setSearchDraft}
                testId={`${TEST_ID}-search-text`}
              />
            </div>
            <div data-testid={`${TEST_ID}-field-status`}>
              <Select
                label="Trạng thái"
                options={statusOptions}
                value={statusDraft}
                onChange={(e) => handleStatusChange(String(e.target.value))}
                data-testid={`${TEST_ID}-status-filter`}
                fullWidth
                size="small"
              />
            </div>
            <div data-testid={`${TEST_ID}-field-severity`}>
              <Select
                label="Mức độ"
                options={severityOptions}
                value={severityDraft}
                onChange={(e) => handleSeverityChange(String(e.target.value))}
                data-testid={`${TEST_ID}-severity-filter`}
                fullWidth
                size="small"
              />
            </div>
            <div data-testid={`${TEST_ID}-field-routeName`}>
              <SearchInput
                label="Đoạn đường"
                config={ROAD_ROUTE_LOOKUP_CONFIG}
                value={routeDraft}
                primaryDisplay={lookupNameOnly(ROAD_ROUTE_SEED, routeDraft)}
                showSecondaryInput={false}
                placeholder="Tất cả đoạn"
                onChange={(item) => handleRouteChange(item.value)}
                onClear={() => handleRouteChange('')}
              />
            </div>
            <div data-testid={`${TEST_ID}-field-incidentType`}>
              <Select
                label="Loại sự cố"
                options={typeOptions}
                value={typeDraft}
                onChange={(e) => handleTypeChange(String(e.target.value))}
                data-testid={`${TEST_ID}-type-filter`}
                fullWidth
                size="small"
              />
            </div>
          </>
        )}
      />
    ),
    [
      searchDraft,
      statusDraft,
      severityDraft,
      routeDraft,
      typeDraft,
      handleSearchClick,
      handleStatusChange,
      handleSeverityChange,
      handleRouteChange,
      handleTypeChange,
      statusOptions,
      severityOptions,
      typeOptions,
      showTableLoading,
    ],
  );

  const uiColumns = useMemo<UiListColumnBootstrap<IncidentDto>[]>(
    () => [
      {
        key: 'code',
        label: 'Mã',
        width: '100px',
        control: 'TEXT',
        allowSort: true,
        render: (row) => (
          <button
            type="button"
            className={styles.codeLink}
            onClick={() => openRow(row, 'view')}
            data-testid={`${TEST_ID}-code-${row.code}`}
          >
            {row.code}
          </button>
        ),
        getDisplayValue: (r) => r.code,
      },
      {
        key: 'title',
        label: 'Tiêu đề',
        width: '220px',
        control: 'TEXT',
        allowSort: true,
        render: (row) => row.title,
        getDisplayValue: (r) => r.title,
      },
      {
        key: 'routeName',
        label: 'Đoạn',
        width: '160px',
        control: 'TEXT',
        allowSort: true,
        render: (row) => row.routeName,
        getDisplayValue: (r) => r.routeName,
      },
      {
        key: 'incidentType',
        label: 'Loại',
        width: '110px',
        control: 'SELECT',
        allowSort: true,
        render: (row) => typeLabel(row.incidentType),
        getDisplayValue: (r) => typeLabel(r.incidentType),
      },
      {
        key: 'severity',
        label: 'Mức độ',
        width: '100px',
        control: 'SELECT',
        allowSort: true,
        render: (row) => severityLabel(row.severity),
        getDisplayValue: (r) => severityLabel(r.severity ?? ''),
      },
      {
        key: 'status',
        label: 'Trạng thái',
        width: '100px',
        control: 'SELECT',
        allowSort: true,
        render: (row) => statusLabel(row.status),
        getDisplayValue: (r) => statusLabel(r.status),
      },
      {
        key: 'requestedAt',
        label: 'Ngày YC',
        width: '150px',
        control: 'DATE',
        allowSort: true,
        render: (row) => formatRequested(row.requestedAt),
        getDisplayValue: (r) => r.requestedAt,
      },
      {
        key: 'detectionId',
        label: 'AI',
        width: '110px',
        control: 'TEXT',
        allowSort: true,
        render: (row) =>
          row.detectionId ? (
            <span className={styles.aiBadge} title={row.detectionId}>
              DET
            </span>
          ) : (
            <span className={styles.aiEmpty}>—</span>
          ),
        getDisplayValue: (r) => r.detectionId ?? '',
      },
    ],
    [openRow],
  );

  const gridColumns = useMemo(
    () => buildDynamicGridColumns(schema, uiColumns),
    [schema, uiColumns],
  );

  const rowMenuItems = useMemo<LinCatalogRowMenuItem[]>(() => {
    const base = buildCatalogRowMenuItems({
      showView: perms.canRead,
      showEdit: perms.canUpdate,
      showCopy: perms.canCreate,
      showDelete: perms.canDelete,
      showHistory: perms.canRead,
    });
    const extras: LinCatalogRowMenuItem[] = [];
    if (perms.canUpdate) {
      extras.push(
        {
          id: 'assign',
          label: 'Giao việc',
          icon: 'fas fa-user-plus',
          separatorBefore: true,
        },
        {
          id: 'close',
          label: 'Đóng',
          icon: 'fas fa-check-circle',
        },
      );
    }
    return [...base, ...extras];
  }, [perms.canRead, perms.canUpdate, perms.canCreate, perms.canDelete]);

  const handleRowMenuSelect = useCallback(
    (action: string) => {
      const row = rowMenu?.row;
      setRowMenu(null);
      if (!row) return;
      switch (action) {
        case 'view':
          openRow(row, 'view');
          break;
        case 'edit':
          openRow(row, 'edit');
          break;
        case 'copy':
          openRow(row, 'copy');
          break;
        case 'delete':
          requestDelete(row);
          break;
        case 'history':
          catalogHistory.openHistory({
            documentType: PAGE_ID,
            documentId: row.id,
            documentCode: row.code,
          });
          break;
        case 'assign':
          openGiaoViec(row);
          break;
        case 'close':
          requestClose(row);
          break;
        default:
          break;
      }
    },
    [
      rowMenu?.row,
      openRow,
      requestDelete,
      openGiaoViec,
      requestClose,
      catalogHistory.openHistory,
    ],
  );

  const emptyMessage =
    search.trim() || statusFilter || severityFilter || routeFilter || typeFilter
      ? 'Không có sự cố phù hợp bộ lọc.'
      : 'Không có dữ liệu sự cố.';

  return (
    <div
      className={styles.page}
      data-catalog-list-page
      data-lin-list-layout="erp-filter-bar"
      data-testid={`${TEST_ID}-page`}
    >
      <LinPageLayout
        kind="catalog"
        listLayoutVariant="erp-filter-bar"
        listHeaderClassName={LIN_ERP_LIST_FILTER_LAYOUT.header}
        listFiltersClassName={LIN_ERP_LIST_FILTER_LAYOUT.filtersHost}
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        header={{
          title: 'Sự cố / Vấn đề',
          titleIconClass: 'fas fa-exclamation-triangle',
          pageId: PAGE_ID,
        }}
        toolbar={fromCatalogToolbar(catalogToolbar)}
        listTitle="Danh sách sự cố"
        listRowMenuHelp
        filters={listFilters}
        filtersTestId={`${TEST_ID}-filters`}
        showTableLoading={showTableLoading}
        pageLoading={pageLoading}
        skeletonRows={8}
        footer={
          <LinCatalogListPagination
            testIdPrefix={TEST_ID}
            page={page}
            pageSize={pageSize}
            totalCount={totalCount}
            onPageChange={handlePageChange}
            onPageSizeChange={handlePageSizeChange}
          />
        }
        modals={
          <>
            <LinCatalogRowActionMenu
              open={rowMenu != null}
              x={rowMenu?.x ?? 0}
              y={rowMenu?.y ?? 0}
              testIdPrefix={TEST_ID}
              onClose={() => setRowMenu(null)}
              onSelect={(action) => {
                handleRowMenuSelect(action);
              }}
              items={rowMenuItems}
            />
            <LinCatalogUiSchemaEditorModal
              isOpen={configOpen}
              onClose={() => setConfigOpen(false)}
              testIdPrefix={TEST_ID}
              catalogKind={CATALOG_KIND}
              loadSchema={catalogUiSchemaService.get}
              saveSchema={catalogUiSchemaService.save}
              onSaved={(next) => {
                setTableConfig({
                  ...DEFAULT_CATALOG_LIST_TABLE_CONFIG,
                  ...catalogListTableConfigFromSchema(next.list),
                  resizable: true,
                });
                reloadSchema();
                setConfigOpen(false);
              }}
              onError={(message) =>
                dispatchAppToast(dispatch, { message, type: 'error' })
              }
              onSuccess={(message) =>
                dispatchAppToast(dispatch, { message, type: 'success' })
              }
            />
            {catalogHistory.modalProps ? (
              <LinCatalogHistoryModal
                {...catalogHistory.modalProps}
                testIdPrefix={TEST_ID}
                onError={(message) =>
                  dispatchAppToast(dispatch, { message, type: 'error' })
                }
              />
            ) : null}
            {pendingDelete ? (
              <div className={styles.confirmOverlay} data-testid={`${TEST_ID}-confirm-delete`}>
                <div className={styles.confirmCard} role="dialog" aria-modal="true">
                  <p>
                    Xóa sự cố «{pendingDelete.code} — {pendingDelete.title}»?
                  </p>
                  <div className={styles.confirmActions}>
                    <Button
                      variant="secondary"
                      size="sm"
                      onClick={() => setPendingDelete(null)}
                    >
                      Hủy
                    </Button>
                    <Button variant="primary" size="sm" onClick={() => void confirmDelete()}>
                      Xóa
                    </Button>
                  </div>
                </div>
              </div>
            ) : null}
            {pendingClose ? (
              <div
                className={styles.confirmOverlay}
                data-testid={`${TEST_ID}-confirm-close`}
                onClick={dismissClose}
                role="presentation"
              >
                <div
                  className={styles.confirmCard}
                  role="dialog"
                  aria-modal="true"
                  onClick={(e) => e.stopPropagation()}
                >
                  <p>Đóng sự cố {pendingClose.code}?</p>
                  <div className={styles.confirmActions}>
                    <Button
                      variant="secondary"
                      size="sm"
                      onClick={dismissClose}
                    >
                      Hủy
                    </Button>
                    <Button variant="primary" size="sm" onClick={() => void confirmClose()}>
                      Đóng sự cố
                    </Button>
                  </div>
                </div>
              </div>
            ) : null}
            <GiaoViecModal
              open={giaoViecOpen}
              context={giaoViecContext}
              onClose={() => setGiaoViecOpen(false)}
              onCreated={(task, ctx) =>
                setChatTarget({
                  taskId: task.id,
                  from: ctx.source,
                  sourceId: ctx.sourceEntityId,
                  title: task.title,
                })
              }
            />
            <TaskChatPanel target={chatTarget} onClose={() => setChatTarget(null)} />
          </>
        }
      >
        <div className={styles.gridWrap} data-testid={`${TEST_ID}-grid-wrap`}>
          <LinCatalogDataGrid
            testIdPrefix={TEST_ID}
            rows={items}
            page={page}
            pageSize={pageSize}
            columns={gridColumns}
            getRowId={(r) => r.id}
            selection={listSelection}
            tableConfig={tableConfig}
            paginateClient={false}
            empty={
              <div className={styles.empty} data-testid={`${TEST_ID}-empty`}>
                {emptyMessage}
              </div>
            }
            onRowOpenActionMenu={({ row, x, y }) => {
              selectActiveRow(row);
              setRowMenu({ row, x, y });
            }}
            onRowDoubleClick={(row) => openRow(row, 'view')}
            rowMenuHintDismissStorageKey={ROW_MENU_HINT_KEY}
          />
        </div>
      </LinPageLayout>
    </div>
  );
};

export default IncidentListPage;
